<?php $title='Jobs'; require 'header.php'; $d=db();$rows=$d->query("SELECT j.*, (SELECT COUNT(*) FROM candidates c WHERE c.job_id=j.id) applicants FROM jobs j ORDER BY j.created_at DESC"); ?>
<div class="admin-head"><div><span class="eyebrow">JOB BOARD</span><h1>Open positions</h1></div><a class="btn dark" href="job_new.php">Add job</a></div><section class="admin-panel"><table><thead><tr><th>Role</th><th>Location</th><th>Mode</th><th>Applicants</th><th>Status</th></tr></thead><tbody><?php while($j=$rows->fetch_assoc()):?><tr><td><strong><?=e($j['title'])?></strong><small><?=e($j['department'])?></small></td><td><?=e($j['location'])?></td><td><?=e($j['work_mode'])?></td><td><?=e((string)$j['applicants'])?></td><td><span class="status-pill <?=e($j['status'])?>"><?=e(status_label($j['status']))?></span></td></tr><?php endwhile;?></tbody></table></section><?php require 'footer.php'; ?>